  WorldPartitionStaticMeshTemplate3D value{};value.asset.name="chunk";value.asset.meshPath=root_/"engine"/"assets"/"model-packs"/"poly-haven"/"rock_09"/"rock_09.aemesh";value.asset.generateLods=false;value.asset.cpuRetention=MeshLodCpuRetention3D::None;value.asset.material.name="world-ground";value.asset.material.textures={root_/"engine/assets/material-packs/ambientcg/ground037/1k/Ground037_1K-JPG_Color.jpg",root_/"engine/assets/material-packs/ambientcg/ground037/1k/Ground037_1K-JPG_Roughness.jpg",64,root_/"engine/assets/material-packs/ambientcg/ground037/1k/Ground037_1K-JPG_NormalDX.jpg"};
  auto rollbackDefinition=value.asset;rollbackDefinition.name="rollback-chunk";const auto rollbackPrepared=library_.PrepareCpu(rollbackDefinition);const auto rollbackRendererBaseline=engine.GetRendererStats();const auto rollbackLibraryBaseline=library_.Stats();engine.SetMeshMemoryBudget(1);const bool rejected=rollbackPrepared&&!library_.AcquirePrepared(*rollbackPrepared);engine.WaitRendererIdle3D();const auto rollbackRenderer=engine.GetRendererStats();const auto rollbackLibrary=library_.Stats();engine.SetMeshMemoryBudget(D3D12Renderer::DefaultMeshMemoryBudgetBytes);if(!rejected||rollbackLibrary.assets!=rollbackLibraryBaseline.assets||rollbackLibrary.liveInstances!=rollbackLibraryBaseline.liveInstances||rollbackRenderer.residentMeshes!=rollbackRendererBaseline.residentMeshes||rollbackRenderer.residentMeshReferences!=rollbackRendererBaseline.residentMeshReferences||rollbackRenderer.pendingGpuReleaseBytes){result_=13;engine.Quit();return;}
  auto textureRollback=value.asset;textureRollback.name="texture-rollback-chunk";textureRollback.material.name="unique-texture-rollback";const auto texturePrepared=library_.PrepareCpu(textureRollback);const auto textureBaseline=engine.GetRendererStats();engine.SetMaterialTextureMemoryBudget(1);const bool textureRejected=texturePrepared&&!library_.AcquirePrepared(*texturePrepared);engine.WaitRendererIdle3D();const auto textureAfter=engine.GetRendererStats();engine.SetMaterialTextureMemoryBudget(D3D12Renderer::DefaultMaterialTextureMemoryBudgetBytes);if(!textureRejected||textureAfter.residentMeshBytes!=textureBaseline.residentMeshBytes||textureAfter.residentTextureAllocationBytes!=textureBaseline.residentTextureAllocationBytes||textureAfter.residentMaterialTextureSets!=textureBaseline.residentMaterialTextureSets||textureAfter.pendingGpuReleaseBytes){result_=14;engine.Quit();return;}
  {StaticMeshWorldChunkSource3D failureSource(library_,value,2);StaticMeshWorldChunkActivationTarget3D failureTarget(engine,library_);failureTarget.SetActivationFailureCheckpointForTesting(1);WorldPartitionSettings3D failureSettings{};failureSettings.spatial={16,0,0,1,1,0x991u};failureSettings.maximumCpuReadyBytes=failureSettings.maximumGpuResidentBytes=failureSettings.maximumPreparationBytesPerUpdate=failureSettings.maximumActivationBytesPerUpdate=8*1024*1024;WorldPartition3D failurePartition(failureSource,failureTarget,failureSettings);failurePartition.Update({});failurePartition.WaitIdle();if(failurePartition.Stats().lastFailure!=WorldPartitionFailureReason3D::ActivationFailed||failureTarget.PendingRetirements()||library_.Stats().liveInstances){result_=15;engine.Quit();return;}failurePartition.Reset();}
  {StaticMeshWorldChunkSource3D wrapSource(library_,value,2);StaticMeshWorldChunkActivationTarget3D wrapTarget(engine,library_);wrapTarget.SetNextActivationIdForTesting((std::numeric_limits<uint64_t>::max)());WorldPartitionSettings3D wrapSettings{};wrapSettings.spatial={16,0,0,1,1,0x992u};wrapSettings.maximumCpuReadyBytes=wrapSettings.maximumGpuResidentBytes=wrapSettings.maximumPreparationBytesPerUpdate=wrapSettings.maximumActivationBytesPerUpdate=8*1024*1024;WorldPartition3D wrapPartition(wrapSource,wrapTarget,wrapSettings);wrapPartition.Update({});wrapPartition.WaitIdle();if(wrapPartition.Stats().lastFailure!=WorldPartitionFailureReason3D::ActivationFailed||library_.Stats().liveInstances){result_=16;engine.Quit();return;}wrapPartition.Reset();}
